      case 2u: storm.ApplyFastOp(TyphoonFastOp::kWeaveColumns, static_cast<std::uint8_t>(storm_control[17] ^ storm_mask[23]), static_cast<std::uint8_t>(storm_control[29] + storm_mask[31])); break;
